build_command:
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const root = fs.realpathSync(process.env.ALIGN_NATIVE_QUAL_REPOSITORY);
const relative = process.argv[1];
assert(!path.isAbsolute(relative) && !relative.includes('\\') && !relative.includes(':'), 'Expected a repository-relative verifier path');
const parts = relative.split('/');
assert(parts.length > 0 && parts.every(part => /^[A-Za-z0-9_.-]+$/.test(part) && part !== '.' && part !== '..'), 'Unsafe verifier path');
const file = parts.reduce((parent, part, index) => (assert(!fs.lstatSync(path.join(parent, part)).isSymbolicLink(), 'Symlink verifier input'), assert(index === parts.length - 1 ? fs.statSync(path.join(parent, part)).isFile() : fs.statSync(path.join(parent, part)).isDirectory(), 'Unexpected verifier member'), path.join(parent, part)), root);
const bytes = fs.readFileSync(file);
assert(bytes.length <= 8 * 1024 * 1024, 'Verifier exceeds bound');
assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'), process.argv[2], 'Verifier content changed');
require(file).main(process.argv.slice(3), root).catch(error => (console.error(error.stack), process.exitCode = 1));

